#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, d;
    cin >> n >> d;

    vector<int> c(n);
    int total = 0;
    for (int &x : c) {
        cin >> x;
        total += x;
    }

    vector<char> dp(total + 1, false);
    dp[0] = true;

    int currentSum = 0;
    for (int x : c) {
        for (int j = currentSum; j >= 0; --j) {
            if (dp[j])
                dp[j + x] = true;
        }
        currentSum += x;
    }

    int mas = 0;
    int day = 0;

    while (true) {
        int x = min(total, mas + d);
        while (x > mas && !dp[x])
            --x;

        if (x == mas) {
            cout << mas << ' ' << day << '\n';
            break;
        }

        mas = x;
        ++day;
    }

    return 0;
}

