        for (int j = total - x; j >= 0; --j) {
            if (dp[j])
                dp[j + x] = true;
        }
    }

    int mas = 0;
    int day = 0;

    while (true) {
        int x = static_cast<int>(min<long long>(total, mas + d));
        while (x > mas && !dp[x])
            --x;

        if (x == mas) {
            cout << mas << ' ' << day << '\n';
            break;
        }

        mas = x;
        ++day;
    }

    return 0;
}

